"""Abstract syntax tree nodes for minisql queries."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, List, Optional, Tuple, Union


@dataclass(frozen=True)
class Literal:
    value: Any
    # One of "int", "float", "str", "bool", "null".  Kept separately from the
    # value because Python considers True == 1 and 1 == 1.0.
    kind: str


@dataclass(frozen=True)
class Column:
    name: str
    index: int = -1


@dataclass(frozen=True)
class Unary:
    op: str
    operand: Expr


@dataclass(frozen=True)
class Binary:
    op: str
    left: Expr
    right: Expr


@dataclass(frozen=True)
class Not:
    operand: Expr


@dataclass(frozen=True)
class IsNull:
    operand: Expr
    negate: bool


@dataclass(frozen=True)
class InList:
    operand: Expr
    items: Tuple[Expr, ...]
    negate: bool


@dataclass(frozen=True)
class Between:
    operand: Expr
    low: Expr
    high: Expr
    negate: bool


@dataclass(frozen=True)
class Like:
    operand: Expr
    pattern: Expr
    negate: bool


@dataclass(frozen=True)
class Func:
    name: str
    args: Tuple[Expr, ...]
    star: bool = False
    aggregate: bool = False


Expr = Union[
    Literal,
    Column,
    Unary,
    Binary,
    Not,
    IsNull,
    InList,
    Between,
    Like,
    Func,
]


@dataclass
class SelectItem:
    expr: Expr
    alias: Optional[str]
    text: str


@dataclass
class OrderItem:
    expr: Expr
    desc: bool
    text: str
    bare_name: Optional[str] = None
    bare_int: Optional[int] = None


@dataclass
class Query:
    distinct: bool
    star: bool
    items: List[SelectItem]
    table: str
    where: Optional[Expr]
    group_by: List[Expr]
    having: Optional[Expr]
    order_by: List[OrderItem]
    limit: Optional[int]
    offset: Optional[int]

