"""Recursive-descent parser for minisql SELECT statements."""

from __future__ import annotations

from typing import List, Optional, Tuple

from ._ast import (
    Between,
    Binary,
    Column,
    Expr,
    Func,
    InList,
    IsNull,
    Like,
    Literal,
    Not,
    OrderItem,
    Query,
    SelectItem,
    Unary,
)
from ._errors import QueryError
from ._lexer import Token, tokenize

_AGGREGATES = frozenset({"COUNT", "SUM", "AVG", "MIN", "MAX"})

# name -> (minimum arguments, maximum arguments or None for no maximum)
_SCALAR_FUNCTIONS = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}

_COMPARISON_OPERATORS = frozenset({"=", "!=", "<>", "<", "<=", ">", ">="})


class Parser:
    def __init__(self, sql: str) -> None:
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # ------------------------------------------------------------------
    # Token helpers
    # ------------------------------------------------------------------
    def _peek(self, offset: int = 0) -> Token:
        index = self.pos + offset
        if index >= len(self.tokens):
            return self.tokens[-1]
        return self.tokens[index]

    def _advance(self) -> Token:
        token = self._peek()
        self.pos += 1
        return token

    def _previous(self) -> Token:
        return self.tokens[self.pos - 1]

    def _at_keyword(self, keyword: str) -> bool:
        token = self._peek()
        return token.kind == "KEYWORD" and token.value == keyword

    def _match_keyword(self, keyword: str) -> bool:
        if self._at_keyword(keyword):
            self.pos += 1
            return True
        return False

    def _expect_keyword(self, keyword: str) -> Token:
        if not self._at_keyword(keyword):
            raise QueryError("syntax error: expected {}".format(keyword))
        return self._advance()

    def _at_op(self, operator: str) -> bool:
        token = self._peek()
        return token.kind == "OP" and token.value == operator

    def _match_op(self, operator: str) -> bool:
        if self._at_op(operator):
            self.pos += 1
            return True
        return False

    def _expect_op(self, operator: str) -> Token:
        if not self._at_op(operator):
            raise QueryError("syntax error: expected {!r}".format(operator))
        return self._advance()

    def _expect_name(self) -> str:
        token = self._peek()
        if token.kind != "IDENT":
            raise QueryError("syntax error: expected a name")
        self.pos += 1
        return str(token.value)

    # ------------------------------------------------------------------
    # Statement
    # ------------------------------------------------------------------
    def parse(self) -> Query:
        self._expect_keyword("SELECT")
        distinct = self._match_keyword("DISTINCT")

        star = False
        items: List[SelectItem] = []
        if self._at_op("*"):
            self._advance()
            star = True
        else:
            items.append(self._parse_select_item())
            while self._match_op(","):
                items.append(self._parse_select_item())

        self._expect_keyword("FROM")
        table = self._expect_name()

        where: Optional[Expr] = None
        if self._match_keyword("WHERE"):
            where = self._parse_expression()

        group_by: List[Expr] = []
        if self._match_keyword("GROUP"):
            self._expect_keyword("BY")
            group_by.append(self._parse_expression())
            while self._match_op(","):
                group_by.append(self._parse_expression())

        having: Optional[Expr] = None
        if self._match_keyword("HAVING"):
            having = self._parse_expression()

        order_by: List[OrderItem] = []
        if self._match_keyword("ORDER"):
            self._expect_keyword("BY")
            order_by.append(self._parse_order_item())
            while self._match_op(","):
                order_by.append(self._parse_order_item())

        limit: Optional[int] = None
        offset: Optional[int] = None
        if self._match_keyword("LIMIT"):
            limit = self._parse_limit_value("LIMIT")
            if self._match_keyword("OFFSET"):
                offset = self._parse_limit_value("OFFSET")

        self._match_op(";")
        if self._peek().kind != "EOF":
            raise QueryError("syntax error: unexpected token {!r}".format(self._peek().value))

        return Query(
            distinct=distinct,
            star=star,
            items=items,
            table=table,
            where=where,
            group_by=group_by,
            having=having,
            order_by=order_by,
            limit=limit,
            offset=offset,
        )

    def _parse_limit_value(self, clause: str) -> int:
        token = self._peek()
        if token.kind != "NUMBER" or not isinstance(token.value, int) or isinstance(token.value, bool):
            raise QueryError("syntax error: {} requires a non-negative integer".format(clause))
        self._advance()
        if token.value < 0:
            raise QueryError("syntax error: {} requires a non-negative integer".format(clause))
        return token.value

    def _parse_select_item(self) -> SelectItem:
        start_pos = self.pos
        first = self._peek()
        expr = self._parse_expression()
        end = self._previous().end
        text = self.sql[first.start:end]

        alias: Optional[str] = None
        if self._match_keyword("AS"):
            alias = self._expect_name()
        elif self._peek().kind == "IDENT":
            alias = str(self._advance().value)

        return SelectItem(expr=expr, alias=alias, text=text)

    def _parse_order_item(self) -> OrderItem:
        start_pos = self.pos
        first = self._peek()
        expr = self._parse_expression()
        end = self._previous().end
        text = self.sql[first.start:end]

        desc = False
        if self._match_keyword("ASC"):
            pass
        elif self._match_keyword("DESC"):
            desc = True

        bare_name: Optional[str] = None
        bare_int: Optional[int] = None
        if self.pos - 1 == start_pos:
            if first.kind == "IDENT" and isinstance(expr, Column):
                bare_name = expr.name
            elif (
                first.kind == "NUMBER"
                and isinstance(expr, Literal)
                and expr.kind == "int"
            ):
                bare_int = int(expr.value)

        return OrderItem(
            expr=expr,
            desc=desc,
            text=text,
            bare_name=bare_name,
            bare_int=bare_int,
        )

    # ------------------------------------------------------------------
    # Expressions, lowest precedence first
    # ------------------------------------------------------------------
    def _parse_expression(self) -> Expr:
        return self._parse_or()

    def _parse_or(self) -> Expr:
        left = self._parse_and()
        while self._match_keyword("OR"):
            right = self._parse_and()
            left = Binary("or", left, right)
        return left

    def _parse_and(self) -> Expr:
        left = self._parse_not()
        while self._match_keyword("AND"):
            right = self._parse_not()
            left = Binary("and", left, right)
        return left

    def _parse_not(self) -> Expr:
        if self._match_keyword("NOT"):
            return Not(self._parse_not())
        return self._parse_comparison()

    def _parse_comparison(self) -> Expr:
        left = self._parse_additive()
        token = self._peek()

        if token.kind == "OP" and token.value in _COMPARISON_OPERATORS:
            operator = str(token.value)
            self._advance()
            right = self._parse_additive()
            return Binary(operator, left, right)

        if self._match_keyword("IS"):
            negate = self._match_keyword("NOT")
            if not self._match_keyword("NULL"):
                raise QueryError("syntax error: expected NULL after IS")
            return IsNull(left, negate)

        if self._match_keyword("NOT"):
            if self._match_keyword("IN"):
                return InList(left, self._parse_in_list(), True)
            if self._match_keyword("BETWEEN"):
                low = self._parse_additive()
                self._expect_keyword("AND")
                high = self._parse_additive()
                return Between(left, low, high, True)
            if self._match_keyword("LIKE"):
                pattern = self._parse_additive()
                return Like(left, pattern, True)
            raise QueryError("syntax error: expected IN, BETWEEN, or LIKE after NOT")

        if self._match_keyword("IN"):
            return InList(left, self._parse_in_list(), False)

        if self._match_keyword("BETWEEN"):
            low = self._parse_additive()
            self._expect_keyword("AND")
            high = self._parse_additive()
            return Between(left, low, high, False)

        if self._match_keyword("LIKE"):
            pattern = self._parse_additive()
            return Like(left, pattern, False)

        return left

    def _parse_in_list(self) -> Tuple[Expr, ...]:
        self._expect_op("(")
        items = [self._parse_expression()]
        while self._match_op(","):
            items.append(self._parse_expression())
        self._expect_op(")")
        return tuple(items)

    def _parse_additive(self) -> Expr:
        left = self._parse_multiplicative()
        while True:
            token = self._peek()
            if token.kind == "OP" and token.value in ("+", "-", "||"):
                operator = str(token.value)
                self._advance()
                right = self._parse_multiplicative()
                left = Binary(operator, left, right)
            else:
                return left

    def _parse_multiplicative(self) -> Expr:
        left = self._parse_unary()
        while True:
            token = self._peek()
            if token.kind == "OP" and token.value in ("*", "/"):
                operator = str(token.value)
                self._advance()
                right = self._parse_unary()
                left = Binary(operator, left, right)
            else:
                return left

    def _parse_unary(self) -> Expr:
        if self._at_op("-"):
            self._advance()
            return Unary("-", self._parse_unary())
        return self._parse_atom()

    def _parse_atom(self) -> Expr:
        token = self._peek()

        if token.kind == "NUMBER":
            self._advance()
            if isinstance(token.value, int) and not isinstance(token.value, bool):
                return Literal(token.value, "int")
            return Literal(token.value, "float")

        if token.kind == "STRING":
            self._advance()
            return Literal(token.value, "str")

        if token.kind == "KEYWORD":
            if token.value == "NULL":
                self._advance()
                return Literal(None, "null")
            if token.value == "TRUE":
                self._advance()
                return Literal(True, "bool")
            if token.value == "FALSE":
                self._advance()
                return Literal(False, "bool")
            raise QueryError("syntax error: unexpected keyword {}".format(token.value))

        if token.kind == "IDENT":
            self._advance()
            if self._at_op("("):
                return self._parse_function(str(token.value))
            return Column(str(token.value))

        if token.kind == "OP" and token.value == "(":
            self._advance()
            expr = self._parse_expression()
            self._expect_op(")")
            return expr

        raise QueryError("syntax error: expected an expression")

    def _parse_function(self, raw_name: str) -> Expr:
        name = raw_name.upper()
        self._expect_op("(")

        if name == "COUNT" and self._at_op("*"):
            self._advance()
            self._expect_op(")")
            return Func("COUNT", (), star=True, aggregate=True)

        args: List[Expr] = []
        if not self._at_op(")"):
            args.append(self._parse_expression())
            while self._match_op(","):
                args.append(self._parse_expression())
        self._expect_op(")")

        if name in _AGGREGATES:
            if len(args) != 1:
                raise QueryError(
                    "function {} expects 1 argument, got {}".format(name, len(args))
                )
            return Func(name, tuple(args), aggregate=True)

        arity = _SCALAR_FUNCTIONS.get(name)
        if arity is None:
            raise QueryError("unknown function: {}".format(raw_name))
        minimum, maximum = arity
        if len(args) < minimum or (maximum is not None and len(args) > maximum):
            if maximum is None:
                expected = "at least {}".format(minimum)
            elif minimum == maximum:
                expected = str(minimum)
            else:
                expected = "{} to {}".format(minimum, maximum)
            raise QueryError(
                "function {} expects {} argument(s), got {}".format(
                    name, expected, len(args)
                )
            )
        return Func(name, tuple(args), aggregate=False)


def parse(sql: str) -> Query:
    return Parser(sql).parse()

