{"content":""""Execution engine for minisql."""

from __future__ import annotations

import csv
import os
import re
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from functools import cmp_to_key, lru_cache
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple

from ._ast import (
    Between,
    Binary,
    Column,
    Expr,
    Func,
    InList,
    IsNull,
    Like,
    Literal,
    Not,
    Query,
    SelectItem,
    Unary,
)
from ._errors import QueryError

_INT_RE = re.compile(r"-?[0-9]+\Z")
_DECIMAL_RE = re.compile(r"-?(?:[0-9]+\.[0-9]*|[0-9]*\.[0-9]+)\Z")


@dataclass
class Table:
    header: List[str]
    rows: List[Tuple[Any, ...]]


@dataclass
class _OrderKey:
    expr: Optional[Expr]
    index: Optional[int]
    desc: bool


@dataclass
class Result:
    columns: List[str]
    rows: List[Tuple[Any, ...]]


# ----------------------------------------------------------------------
# Loading CSV tables
# ----------------------------------------------------------------------
def _convert_field(field: str) -> Any:
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _DECIMAL_RE.fullmatch(field):
        return float(field)
    return field


def load_table(directory: Any, name: str) -> Table:
    try:
        directory = os.fspath(directory)
    except TypeError:
        raise QueryError("invalid directory")

    path = os.path.join(directory, name + ".csv")
    try:
        with open(path, "r", newline="", encoding="utf-8") as handle:
            reader = csv.reader(handle)
            try:
                header = next(reader)
            except StopIteration:
                raise QueryError("table {!r} is empty".format(name))

            rows: List[Tuple[Any, ...]] = []
            for line_number, raw in enumerate(reader, start=2):
                if len(raw) != len(header):
                    raise QueryError(
                        "table {!r}: row {} has {} field(s), expected {}".format(
                            name, line_number, len(raw), len(header)
                        )
                    )
                rows.append(tuple(_convert_field(field) for field in raw))
    except FileNotFoundError:
        raise QueryError("table {!r} not found".format(name))
    except (OSError, UnicodeError, csv.Error) as exc:
        raise QueryError("cannot read table {!r}: {}".format(name, exc))

    return Table(header, rows)


# ----------------------------------------------------------------------
# Expression helpers
# ----------------------------------------------------------------------
def _is_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _type_name(value: Any) -> str:
    if isinstance(value, bool):
        return "a boolean"
    if _is_number(value):
        return "a number"
    if isinstance(value, str):
        return "a string"
    return "a value"


def _children(expr: Expr) -> Tuple[Expr, ...]:
    if isinstance(expr, Unary):
        return (expr.operand,)
    if isinstance(expr, Binary):
        return (expr.left, expr.right)
    if isinstance(expr, Not):
        return (expr.operand,)
    if isinstance(expr, IsNull):
        return (expr.operand,)
    if isinstance(expr, InList):
        return (expr.operand,) + expr.items
    if isinstance(expr, Between):
        return (expr.operand, expr.low, expr.high)
    if isinstance(expr, Like):
        return (expr.operand, expr.pattern)
    if isinstance(expr, Func):
        return expr.args
    return ()


def _expr_equal(left: Expr, right: Expr) -> bool:
    if type(left) is not type(right):
        return False
    if isinstance(left, Literal):
        return left.kind == right.kind and left.value == right.value
    if isinstance(left, Column):
        return left.index == right.index
    if isinstance(left, Unary):
        return left.op == right.op and _expr_equal(left.operand, right.operand)
    if isinstance(left, Binary):
        return (
            left.op == right.op
            and _expr_equal(left.left, right.left)
            and _expr_equal(left.right, right.right)
        )
    if isinstance(left, Not):
        return _expr_equal(left.operand, right.operand)
    if isinstance(left, IsNull):
        return left.negate == right.negate and _expr_equal(
            left.operand, right.operand
        )
    if isinstance(left, InList):
        return (
            left.negate == right.negate
            and _expr_equal(left.operand, right.operand)
            and len(left.items) == len(right.items)
            and all(_expr_equal(a, b) for a, b in zip(left.items, right.items))
        )
    if isinstance(left, Between):
        return (
            left.negate == right.negate
            and _expr_equal(left.operand, right.operand)
            and _expr_equal(left.low, right.low)
            and _expr_equal(left.high, right.high)
        )
    if isinstance(left, Like):
        return (
            left.negate == right.negate
            and _expr_equal(left.operand, right.operand)
            and _expr_equal(left.pattern, right.pattern)
        )
    if isinstance(left, Func):
        return (
            left.name == right.name
            and left.star == right.star
            and left.aggregate == right.aggregate
            and len(left.args) == len(right.args)
            and all(_expr_equal(a, b) for a, b in zip(left.args, right.args))
        )
    return left == right


def _has_aggregate(expr: Expr) -> bool:
    if isinstance(expr, Func) and expr.aggregate:
        return True
    return any(_has_aggregate(child) for child in _children(expr))


def _check_aggregates(expr: Expr, inside_aggregate: bool = False) -> None:
    if isinstance(expr, Func) and expr.aggregate:
        if inside_aggregate:
            raise QueryError("aggregate functions cannot be nested")
        for arg in expr.args:
            _check_aggregates(arg, True)
        return
    for child in _children(expr):
        _check_aggregates(child, inside_aggregate)


def _bind_expr(
    expr: Expr, lookup: Dict[str, Tuple[int, str]]
) -> Expr:
    if isinstance(expr, Literal):
        return expr
    if isinstance(expr, Column):
        if expr.index >= 0:
            return expr
        entry = lookup.get(expr.name.casefold())
        if entry is None:
            raise QueryError("unknown column: {}".format(expr.name))
        index, header_name = entry
        return Column(header_name, index)
    if isinstance(expr, Unary):
        return Unary(expr.op, _bind_expr(expr.operand, lookup))
    if isinstance(expr, Binary):
        return Binary(
            expr.op,
            _bind_expr(expr.left, lookup),
            _bind_expr(expr.right, lookup),
        )
    if isinstance(expr, Not):
        return Not(_bind_expr(expr.operand, lookup))
    if isinstance(expr, IsNull):
        return IsNull(_bind_expr(expr.operand, lookup), expr.negate)
    if isinstance(expr, InList):
        return InList(
            _bind_expr(expr.operand, lookup),
            tuple(_bind_expr(item, lookup) for item in expr.items),
            expr.negate,
        )
    if isinstance(expr, Between):
        return Between(
            _bind_expr(expr.operand, lookup),
            _bind_expr(expr.low, lookup),
            _bind_expr(expr.high, lookup),
            expr.negate,
        )
    if isinstance(expr, Like):
        return Like(
            _bind_expr(expr.operand, lookup),
            _bind_expr(expr.pattern, lookup),
            expr.negate,
        )
    if isinstance(expr, Func):
        return Func(
            expr.name,
            tuple(_bind_expr(arg, lookup) for arg in expr.args),
            expr.star,
            expr.aggregate,
        )
    raise QueryError("invalid expression")


def _validate_grouped(expr: Expr, group_exprs: Sequence[Expr]) -> None:
    if any(_expr_equal(expr, group_expr) for group_expr in group_exprs):
        return
    if isinstance(expr, Literal):
        return
    if isinstance(expr, Func) and expr.aggregate:
        return
    if isinstance(expr, Column):
        raise QueryError(
            "column {} must appear in GROUP BY or be used in an aggregate".format(
                expr.name
            )
        )
    for child in _children(expr):
        _validate_grouped(child, group_exprs)


# ----------------------------------------------------------------------
# Scalar semantics
# ----------------------------------------------------------------------
def _to_bool(value: Any) -> Optional[bool]:
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    raise QueryError("condition must be a boolean")


def _truth(value: Any) -> bool:
    return _to_bool(value) is True


def _not3(value: Optional[bool]) -> Optional[bool]:
    if value is None:
        return None
    return not value


def _and3(left: Optional[bool], right: Optional[bool]) -> Optional[bool]:
    if left is False or right is False:
        return False
    if left is None or right is None:
        return None
    return True


def _or3(left: Optional[bool], right: Optional[bool]) -> Optional[bool]:
    if left is True or right is True:
        return True
    if left is None or right is None:
        return None
    return False


def _compare_values(left: Any, right: Any) -> int:
    if _is_number(left) and _is_number(right):
        if left < right:
            return -1
        if left > right:
            return 1
        return 0
    if isinstance(left, bool) and isinstance(right, bool):
        if left < right:
            return -1
        if left > right:
            return 1
        return 0
    if isinstance(left, str) and isinstance(right, str):
        if left < right:
            return -1
        if left > right:
            return 1
        return 0
    raise QueryError(
        "cannot compare {} with {}".format(_type_name(left), _type_name(right))
    )


def _sql_compare(operator: str, left: Any, right: Any) -> Optional[bool]:
    if left is None or right is None:
        return None
    comparison = _compare_values(left, right)
    if operator == "=":
        return comparison == 0
    if operator in ("!=", "<>"):
        return comparison != 0
    if operator == "<":
        return comparison < 0
    if operator == "<=":
        return comparison <= 0
    if operator == ">":
        return comparison > 0
    if operator == ">=":
        return comparison >= 0
    raise QueryError("unknown comparison operator: {}".format(operator))


@lru_cache(maxsize=128)
def _like_pattern(pattern: str) -> "re.Pattern[str]":
    parts = []
    for character in pattern:
        if character == "%":
            parts.append(".*")
        elif character == "_":
            parts.append(".")
        else:
            parts.append(re.escape(character))
    return re.compile("".join(parts), re.DOTALL)


def _like(value: str, pattern: str) -> bool:
    return _like_pattern(pattern).fullmatch(value) is not None


def _text(value: Any) -> str:
    if isinstance(value, str):
        return value
    return str(value)


def _round_to_int(value: Any) -> int:
    try:
        return int(
            Decimal(str(value)).quantize(Decimal(1), rounding=ROUND_HALF_UP)
        )
    except (InvalidOperation, ValueError, OverflowError):
        raise QueryError("cannot round value")


def _round_to_places(value: Any, places: int) -> float:
    try:
        quantum = Decimal(1).scaleb(-places)
        rounded = Decimal(str(value)).quantize(quantum, rounding=ROUND_HALF_UP)
        return float(rounded)
    except (InvalidOperation, ValueError, OverflowError):
        raise QueryError("cannot round value")


# ----------------------------------------------------------------------
# Expression evaluation
# ----------------------------------------------------------------------
def evaluate(expr: Expr, row: Optional[Tuple[Any, ...]], group: Optional[List[Tuple[Any, ...]]]) -> Any:
    if isinstance(expr, Literal):
        return expr.value

    if isinstance(expr, Column):
        if row is None:
            raise QueryError("column {} is not available".format(expr.name))
        return row[expr.index]

    if isinstance(expr, Unary):
        value = evaluate(expr.operand, row, group)
        if value is None:
            return None
        if not _is_number(value):
            raise QueryError("unary - requires a number")
        return -value

    if isinstance(expr, Not):
        return _not3(_to_bool(evaluate(expr.operand, row, group)))

    if isinstance(expr, Binary):
        return _evaluate_binary(expr, row, group)

    if isinstance(expr, IsNull):
        value = evaluate(expr.operand, row, group)
        return (value is None) != expr.negate

    if isinstance(expr, InList):
        return _evaluate_in_list(expr, row, group)

    if isinstance(expr, Between):
        value = evaluate(expr.operand, row, group)
        low = evaluate(expr.low, row, group)
        high = evaluate(expr.high, row, group)
        result = _and3(
            _sql_compare("<=", low, value),
            _sql_compare("<=", value, high),
        )
        return _not3(result) if expr.negate else result

    if isinstance(expr, Like):
        value = evaluate(expr.operand, row, group)
        pattern = evaluate(expr.pattern, row, group)
        if value is None or pattern is None:
            return None
        if not isinstance(value, str) or not isinstance(pattern, str):
            raise QueryError("LIKE requires string operands")
        matched = _like(value, pattern)
        return not matched if expr.negate else matched

    if isinstance(expr, Func):
        if expr.aggregate:
            return _evaluate_aggregate(expr, group)
        return _evaluate_scalar(expr, row, group)

    raise QueryError("invalid expression")


def _evaluate_binary(
    expr: Binary, row: Optional[Tuple[Any, ...]], group: Optional[List[Tuple[Any, ...]]]
) -> Any:
    operator = expr.op

    if operator == "and":
        left = _to_bool(evaluate(expr.left, row, group))
        if left is False:
            return False
        right = _to_bool(evaluate(expr.right, row, group))
        return _and3(left, right)

    if operator == "or":
        left = _to_bool(evaluate(expr.left, row, group))
        if left is True:
            return True
        right = _to_bool(evaluate(expr.right, row, group))
        return _or3(left, right)

    left = evaluate(expr.left, row, group)
    right = evaluate(expr.right, row, group)

    if operator in ("+", "-", "*", "/"):
        if left is None or right is None:
            return None
        if not _is_number(left) or not _is_number(right):
            raise QueryError("arithmetic requires numeric operands")
        if operator == "/":
            if right == 0:
                return None
            return left / right
        if isinstance(left, int) and isinstance(right, int):
            if operator == "+":
                return left + right
            if operator == "-":
                return left - right
            return left * right
        left_float = float(left)
        right_float = float(right)
        if operator == "+":
            return left_float + right_float
        if operator == "-":
            return left_float - right_float
        return left_float * right_float

    if operator == "||":
        if left is None or right is None:
            return None
        return _text(left) + _text(right)

    return _sql_compare(operator, left, right)


def _evaluate_in_list(
    expr: InList, row: Optional[Tuple[Any, ...]], group: Optional[List[Tuple[Any, ...]]]
) -> Optional[bool]:
    value = evaluate(expr.operand, row, group)
    if value is None:
        return None

    saw_null = False
    for item_expr in expr.items:
        item = evaluate(item_expr, row, group)
        if item is None:
            saw_null = True
            continue
        if _sql_compare("=", value, item) is True:
            result: Optional[bool] = True
            return _not3(result) if expr.negate else result

    result = None if saw_null else False
    return _not3(result) if expr.negate else result


def _evaluate_scalar(
    expr: Func, row: Optional[Tuple[Any, ...]], group: Optional[List[Tuple[Any, ...]]]
) -> Any:
    name = expr.name

    if name == "COALESCE":
        for argument in expr.args:
            value = evaluate(argument, row, group)
            if value is not None:
                return value
        return None

    values = [evaluate(argument, row, group) for argument in expr.args]
    if any(value is None for value in values):
        return None

    if name == "LOWER":
        value = values[0]
        if not isinstance(value, str):
            raise QueryError("LOWER requires a string")
        return value.lower()

    if name == "UPPER":
        value = values[0]
        if not isinstance(value, str):
            raise QueryError("UPPER requires a string")
        return value.upper()

    if name == "LENGTH":
        value = values[0]
        if not isinstance(value, str):
            raise QueryError("LENGTH requires a string")
        return len(value)

    if name == "ABS":
        value = values[0]
        if not _is_number(value):
            raise QueryError("ABS requires a number")
        return abs(value)

    if name == "ROUND":
        value = values[0]
        if not _is_number(value):
            raise QueryError("ROUND requires a number")
        if len(values) == 1:
            return _round_to_int(value)
        places = values[1]
        if not isinstance(places, int) or isinstance(places, bool):
            raise QueryError("ROUND requires an integer number of decimal places")
        return _round_to_places(value, places)

    raise QueryError("unknown function: {}".format(name))


def _evaluate_aggregate(
    expr: Func, group: Optional[List[Tuple[Any, ...]]]
) -> Any:
    if group is None:
        raise QueryError("aggregate function used outside a grouped query")

    name = expr.name
    if expr.star:
        return len(group)

    argument = expr.args[0]

    if name == "COUNT":
        count = 0
        for row in group:
            if evaluate(argument, row, None) is not None:
                count += 1
        return count

    values: List[Any] = []
    for row in group:
        value = evaluate(argument, row, None)
        if value is not None:
            values.append(value)

    if not values:
        return None

    if name == "SUM":
        for value in values:
            if not _is_number(value):
                raise QueryError("SUM requires numeric values")
        total: Any = 0
        for value in values:
            total += value
        return total

    if name == "AVG":
        for value in values:
            if not _is_number(value):
                raise QueryError("AVG requires numeric values")
        total = 0
        for value in values:
            total += value
        return total / len(values)

    if name == "MIN":
        best = values[0]
        for value in values[1:]:
            if _compare_values(value, best) < 0:
                best = value
        return best

    if name == "MAX":
        best = values[0]
        for value in values[1:]:
            if _compare_values(value, best) > 0:
                best = value
        return best

    raise QueryError("unknown aggregate function: {}".format(name))


# ----------------------------------------------------------------------
# Query execution
# ----------------------------------------------------------------------
def _value_key(value: Any) -> Tuple[Any, ...]:
    if value is None:
        return (0,)
    if isinstance(value, bool):
        return (1, value)
    if _is_number(value):
        return (2, value)
    if isinstance(value, str):
        return (3, value)
    return (4, repr(value))


def _compare_for_sort(left: Any, right: Any, descending: bool) -> int:
    if left is None and right is None:
        return 0
    if left is None:
        return 1 if descending else -1
    if right is None:
        return -1 if descending else 1
    comparison = _compare_values(left, right)
    return -comparison if descending else comparison


def execute(query: Query, table: Table) -> Result:
    lookup: Dict[str, Tuple[int, str]] = {}
    for index, header_name in enumerate(table.header):
        lookup.setdefault(header_name.casefold(), (index, header_name))

    if query.star:
        raw_items = [
            SelectItem(Column(header_name, index), None, header_name)
            for index, header_name in enumerate(table.header)
        ]
    else:
        raw_items = query.items

    items = [
        SelectItem(_bind_expr(item.expr, lookup), item.alias, item.text)
        for item in raw_items
    ]

    columns: List[str] = []
    for item in items:
        if item.alias is not None:
            columns.append(item.alias)
        elif isinstance(item.expr, Column):
            columns.append(item.expr.name)
        else:
            columns.append(item.text)

    output_lookup: Dict[str, int] = {}
    for index, column_name in enumerate(columns):
