def _round_decimal(value: Any, places: int) -> Decimal:
    try:
        decimal_value = Decimal(str(value))
        integer_digits = max(decimal_value.adjusted() + 1, 1)
        fractional_digits = max(places, 0)
        with localcontext() as context:
            context.prec = max(28, integer_digits + fractional_digits + 5)
            quantum = Decimal(1).scaleb(-places)
            return decimal_value.quantize(quantum, rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError, OverflowError):
        raise QueryError("cannot round value")


def _round_to_int(value: Any) -> int:
    return int(_round_decimal(value, 0))


def _round_to_places(value: Any, places: int) -> float:
    return float(_round_decimal(value, places))

